const DEFAULT_API = '/api/v1';
function readStoredUser(){try{const value=JSON.parse(localStorage.getItem('gl_user')||'null');return value&&typeof value==='object'?value:null}catch(error){console.warn('Ignoring invalid cached learner profile',error);return null}}
const SUBJECT_ICONS=['∑','Aa','⚗','◎','π','⌘','◇','∴'];
const state = {selectedTopic:null,view:'home',register:false,token:localStorage.getItem('gl_token')||'',user:readStoredUser(),api:localStorage.getItem('gl_api')||DEFAULT_API,quizIndex:0,quizChoice:null,quizScore:0,quizDone:false,quizQuestions:[],quizSubject:'',quizAnswers:[],quizDeadline:0,quizTimer:null,quizGrading:false,quizFeedback:'',logs:[],tests:[],journal:[]};

const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2500)}
function api(path,opts={}){if(!state.api)throw new Error('Set the API base URL in your account settings to sync data.');const isForm=opts.body instanceof FormData;const {timeoutMs,...fetchOpts}=opts;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),timeoutMs||(isForm?90000:45000));return fetch(state.api.replace(/\/$/,'')+path,{...fetchOpts,signal:opts.signal||controller.signal,headers:{...(!isForm?{'Content-Type':'application/json'}:{}),...(state.token?{Authorization:'Bearer '+state.token}:{}),...(opts.headers||{})}}).then(async r=>{const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Request failed ('+r.status+')');return d}).catch(error=>{if(error.name==='AbortError')throw new Error('Connection timed out. Check your internet connection and API URL, then retry.');throw error}).finally(()=>clearTimeout(timeout))}
function showView(view){state.view=view;$$('.view').forEach(el=>el.classList.toggle('active',el.id===`view-${view}`));$$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#crumb').textContent=({home:'Overview',subjects:'My subjects',tutor:'AI tutor',practice:'Practice',journal:'Learning journal',tests:'Test tracker',documents:'Study files',notifications:'Notifications',profile:'Account'})[view]||view;window.scrollTo({top:0,behavior:'smooth'});if(view==='practice')renderQuiz();if(view==='profile')fillProfile();if(view==='subjects')renderSubjects();if(view==='tutor'){renderTutorMessages();initTutor();}if(view==='documents')loadDocuments();if(view==='notifications')loadNotificationSettings();}
function subjectIdentity(value){const cleaned=String(value??'').normalize('NFKC').trim().replace(/\s+/g,' ').toLocaleLowerCase();const aliases={'english':'english language','core math':'core mathematics','core maths':'core mathematics','math':'core mathematics','maths':'core mathematics','add math':'additional mathematics','add maths':'additional mathematics','elective mathematics':'additional mathematics','elective maths':'additional mathematics','comp sci':'computer science','computer science':'computer science','social studies':'social studies','ict':'ict'};return aliases[cleaned]||cleaned}
function getLearnerSubjects(){const raw=Array.isArray(state.user?.subjects)?state.user.subjects:[];const seen=new Set();return raw.map(s=>String(s??'').trim().replace(/\s+/g,' ')).filter(s=>{if(!s)return false;const key=subjectIdentity(s);if(seen.has(key))return false;seen.add(key);return true})}
function subjectCard(name,i){const description=state.user?.class_level?state.user.class_level+' · Your subject':'Your subject';return '<button type="button" class="subject-card" data-subject="'+esc(name)+'"><span class="subject-icon">'+SUBJECT_ICONS[i%SUBJECT_ICONS.length]+'</span><span class="subject-meta"><b>'+esc(name)+'</b><small>'+esc(description)+'</small></span><span class="subject-arrow" aria-hidden="true">›</span></button>'}
function renderSubjects(){const subjects=getLearnerSubjects();$('#home-subjects').innerHTML=subjects.length?subjects.slice(0,4).map((s,i)=>subjectCard(s,i)).join():'<p class="empty-state">No subjects registered yet. Add your subjects in Account settings to see them here.</p>';$('#all-subjects').innerHTML=subjects.length?subjects.map((s,i)=>subjectCard(s,i)).join():'<div class="record"><h3>No subjects registered yet</h3><p>Add the subjects you study in Account settings. GetLearny will use that list without adding a second, hardcoded list.</p><button type="button" class="button button-primary" data-go="profile">Open account settings →</button></div>';}
function selectSubject(name){
 const s={name:String(name||''),code:({'chemistry':'SCI','biology':'SCI','integrated science':'SCI','english':'ENG','english language':'ENG','core math':'MATH','core mathematics':'MATH','mathematics':'MATH','add math':'EMATH','additional mathematics':'EMATH','social studies':'SOC','computer science':'ICT','ict':'ICT'}[String(name||'').trim().toLowerCase()]||String(name||'').toUpperCase().replace(/[^A-Z0-9_-]/g,'').slice(0,30)),topic:String(name||'')};state.selectedTopic=s.topic;showView('subjects');const panel=$('#lesson-panel');panel.classList.remove('hidden');panel.dataset.subjectName=s.name;$('#view-subjects').querySelectorAll(':scope > .eyebrow, :scope > h1, :scope > .lead, #all-subjects').forEach(el=>{el.classList.add('subject-browse-hidden');el.setAttribute('aria-hidden','true')});
 panel.innerHTML='<div class="subject-workspace"><button type="button" class="button button-light subject-back-button" id="subject-back-to-list">← All subjects</button><div class="subject-workspace-head"><div><div class="eyebrow">YOUR SUBJECT WORKSPACE</div><h2 id="selected-topic-heading">'+esc(s.name)+'</h2><p>Learn, organise your notes, and practise with AI in one place.</p></div><span class="subject-chip">Personal study space</span></div><div class="subject-tool-grid"><button type="button" class="subject-tool active" data-subject-tab="learn"><span>✦</span><b>Learn & revise</b><small>Topics and lessons</small></button><button type="button" class="subject-tool" data-subject-tab="materials"><span>↥</span><b>Study materials</b><small>Upload notes and PDFs</small></button><button type="button" class="subject-tool" data-subject-tab="practice"><span>◷</span><b>Timed practice</b><small>Exam-style questions</small></button></div><div id="subject-learn" class="subject-tab-panel"><div class="lesson-actions"><button class="button button-primary" id="generate-lesson">Generate lesson →</button><button class="button button-light" id="log-complete">Mark topic complete</button></div><div id="topic-catalog" class="topic-catalog"><p>Loading topics from GetLearny…</p></div><div id="lesson-content" class="lesson-content"></div></div><div id="subject-materials" class="subject-tab-panel hidden"><div class="material-upload-heading"><div><h3>Upload to '+esc(s.name)+'</h3><p>Save notes to this subject and ask AI to explain readable material.</p></div><span class="material-upload-icon">↥</span></div><form id="subject-material-form" class="subject-upload-form"><label class="upload-dropzone"><span class="upload-drop-icon">＋</span><b>Choose a study material</b><small>PDF, TXT, Markdown, CSV, JSON, PNG, JPG or WEBP · up to 100 MB</small><input id="subject-material-file" type="file" accept=".pdf,.txt,.md,.markdown,.csv,.json,.png,.jpg,.jpeg,.webp,application/pdf,text/plain,text/markdown,text/csv,application/json,image/png,image/jpeg,image/webp" required></label><label>Material title (optional)<input name="material_title" maxlength="120" placeholder="e.g. Cell division class notes"></label><button class="button button-primary" type="submit">Upload material →</button><p id="subject-material-message" class="form-message" role="status"></p></form><div class="section-heading"><div><h3>Your materials</h3><p>Files saved under '+esc(s.name)+'</p></div><button class="text-button" type="button" id="subject-material-refresh">Refresh ↻</button></div><div id="subject-material-list" class="record-list"></div></div><div id="subject-practice" class="subject-tab-panel hidden"><div class="subject-practice-box"><h3>Practice '+esc(s.name)+'</h3><p>Timed questions, one minute per question. Answers lock and grade when time runs out.</p><button class="button button-primary" id="subject-generate-practice">Generate timed practice →</button></div></div></div>';
 panel.scrollIntoView({behavior:'smooth',block:'start'});$('#subject-back-to-list').onclick=()=>{panel.classList.add('hidden');panel.innerHTML='';panel.removeAttribute('data-subject');$('#view-subjects').querySelectorAll('.subject-browse-hidden').forEach(el=>{el.classList.remove('subject-browse-hidden');el.removeAttribute('aria-hidden')});window.scrollTo({top:0,behavior:'smooth'})};$('#generate-lesson').onclick=()=>generateLesson(s);$('#log-complete').onclick=()=>saveLearningLog(s);renderTopicCatalog(s,panel);
 panel.querySelectorAll('[data-subject-tab]').forEach(btn=>btn.onclick=()=>{panel.querySelectorAll('[data-subject-tab]').forEach(x=>x.classList.toggle('active',x===btn));['learn','materials','practice'].forEach(tab=>panel.querySelector('#subject-'+tab).classList.toggle('hidden',tab!==btn.dataset.subjectTab));if(btn.dataset.subjectTab==='materials')loadSubjectMaterials(s.name)});
 $('#subject-material-refresh').onclick=()=>loadSubjectMaterials(s.name);$('#subject-material-form').addEventListener('submit',e=>uploadSubjectMaterial(e,s.name));$('#subject-generate-practice').onclick=()=>{state.quizSubject=s.name;state.quizQuestions=[];showView('practice');renderQuiz()};
}
async function renderTopicCatalog(s,panel){const target=panel.querySelector('#topic-catalog');try{const r=await api(`/topics?subject=${encodeURIComponent(s.code)}&limit=100`);const topics=r.topics||[];if(!topics.length)throw new Error('No published topics are available for this subject yet.');target.innerHTML=`<div class="catalog-heading"><b>Topic catalogue</b><span>${topics.length} topics</span></div><div class="topic-choice-list">${topics.map(t=>`<button type="button" class="topic-choice ${t.title===state.selectedTopic?'selected':''}" data-topic="${esc(t.title)}"><span><b>${esc(t.title)}</b><small>${esc(t.description||'Select to study this topic')}</small></span><span aria-hidden="true">→</span></button>`).join('')}</div>`;target.querySelectorAll('[data-topic]').forEach(button=>button.addEventListener('click',()=>{state.selectedTopic=button.dataset.topic;panel.querySelector('#selected-topic-heading').textContent=`${s.name}: ${state.selectedTopic}`;target.querySelectorAll('[data-topic]').forEach(item=>item.classList.toggle('selected',item===button));panel.querySelector('#lesson-content').innerHTML=''}))}catch(error){target.innerHTML=`<div class="record"><h3>Topic catalogue unavailable</h3><p>${esc(error.message)}</p><p>GetLearny will not invent topics. Reconnect and retry to load the published catalogue.</p><button type="button" class="button button-light" id="retry-topic-catalog">Retry catalogue</button></div>`;target.querySelector('#retry-topic-catalog').addEventListener('click',()=>renderTopicCatalog(s,panel))}}
function markdownLite(text){return esc(text).replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h3>$1</h3>').replace(/^# (.*)$/gm,'<h2>$1</h2>').replace(/\*\*(.*?)\*\*/g,'<b>$1</b>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/^\- (.*)$/gm,'• $1').replace(/\n\n/g,'</p><p>').replace(/\n/g,'<br>')}
async function generateLesson(s){const topic=state.selectedTopic||s.topic;const target=$('#lesson-content');if(!state.token){target.innerHTML='<div class="lesson-panel"><h3>Sign in to generate your lesson</h3><p>Connect your account to use the live lesson service and save your progress across devices.</p><button class="button button-primary" id="lesson-sign-in">Open account →</button></div>';$('#lesson-sign-in').onclick=()=>showView('profile');return}target.innerHTML='<p>Preparing your lesson…</p>';try{const r=await api('/lessons/generate',{method:'POST',body:JSON.stringify({subject:s.name,topic,level:state.user?.class_level||'Not specified',exam:'WASSCE'})});target.innerHTML=`<div class="lesson-panel">${markdownLite(r.lesson)}</div>`}catch(e){target.innerHTML='<div class="lesson-panel"><h3>Lesson unavailable</h3><p>'+esc(e.message)+'</p><p>Check GEMINI_API_KEY, GEMINI_MODEL and Gemini API access in the API deployment. No sample lesson was substituted.</p></div>'}}

async function saveLearningLog(s){const topic=state.selectedTopic||s.topic;try{await api('/learning-logs',{method:'POST',body:JSON.stringify({subject:s.name,topic,minutes_spent:15,status:'completed',notes:'Completed from the web learning path'})});toast('Topic completion synced.')}catch(e){toast(e.message)}loadDashboard()}
async function stopQuizTimer(){if(state.quizTimer){clearInterval(state.quizTimer);state.quizTimer=null}}
function formatQuizTime(ms){const n=Math.max(0,Math.ceil(ms/1000));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function startQuizTimer(){stopQuizTimer();state.quizDeadline=Date.now()+Math.max(1,state.quizQuestions.length)*60000;state.quizTimer=setInterval(()=>{const left=state.quizDeadline-Date.now(),el=$('#quiz-countdown');if(el){el.textContent=formatQuizTime(left);el.classList.toggle('timer-warning',left<=60000)}if(left<=0)finishTimedQuiz(true)},250)}
async function finishTimedQuiz(expired=false){if(state.quizDone||!state.quizQuestions.length)return;state.quizDone=true;state.quizGrading=true;stopQuizTimer();if(expired)toast('Time is up. Your answers are locked. Grading now…');renderQuiz();try{const graded=await api('/practice/grade',{method:'POST',timeoutMs:25000,body:JSON.stringify({subject:state.quizSubject,questions:state.quizQuestions.map(q=>({question:q.question,options:q.options,answer:q.answer,explanation:q.explanation||''})),answers:state.quizAnswers})});state.quizScore=Number(graded.score)||0;state.quizFeedback=graded.feedback||'';try{await api('/tests',{method:'POST',body:JSON.stringify({subject:state.quizSubject,title:'Timed AI practice',score:state.quizScore,max_score:state.quizQuestions.length})})}catch(e){toast('Grade ready, but result could not be saved: '+e.message)}}catch(e){state.quizScore=state.quizQuestions.reduce((n,q,i)=>n+(Number(state.quizAnswers[i])===Number(q.answer)?1:0),0);state.quizFeedback='AI review is unavailable right now. Your multiple-choice answers were checked against the saved answer key; reconnect to get personalised AI feedback.';try{await api('/tests',{method:'POST',body:JSON.stringify({subject:state.quizSubject,title:'Timed AI practice',score:state.quizScore,max_score:state.quizQuestions.length})})}catch{}}finally{state.quizGrading=false;renderQuiz();loadDashboard()}}
function renderQuiz(){
 const card=$('#quiz-card');
 if(!state.token){stopQuizTimer();card.innerHTML='<h2>Sign in to practise</h2><p>AI-generated questions and results are saved to your account.</p><button class="button button-primary" id="practice-signin">Open account →</button>';$('#practice-signin').onclick=()=>showView('profile');return}
 const subjects=getLearnerSubjects();
 if(!state.quizQuestions.length){stopQuizTimer();if(!subjects.length){card.innerHTML='<div class="practice-builder"><h2>No registered subjects</h2><p>Add the subjects you study in Account settings first. Practice will use that list, without built-in duplicates.</p><button type="button" class="button button-primary" id="practice-add-subjects">Open account settings →</button></div>';$('#practice-add-subjects').onclick=()=>showView('profile');return;}card.innerHTML='<div class="practice-builder"><div class="practice-builder-heading"><span class="practice-builder-icon">✦</span><div><div class="eyebrow">AI EXAM BUILDER</div><h2>Build your practice set</h2><p>Choose a subject and topic. Your timer is calculated from the number of questions.</p></div></div><div class="practice-form-grid"><label for="practice-subject"><span>Subject</span><select id="practice-subject">'+subjects.map(s=>'<option value="'+esc(s)+'" '+(s===state.quizSubject?'selected':'')+'>'+esc(s)+'</option>').join('')+'</select></label><label for="practice-topic"><span>Topic <em>(optional)</em></span><input id="practice-topic" maxlength="200" placeholder="e.g. quadratic equations"></label><label for="practice-count"><span>Number of questions</span><select id="practice-count"><option value="5">5 questions</option><option value="10" selected>10 questions</option><option value="15">15 questions</option></select></label></div><div class="practice-meta" id="practice-time-preview"><span>◷ <b>10 minutes</b> estimated</span><span>One minute per question</span><span>Auto-submit and AI grading</span></div><button class="button button-primary practice-generate-button" id="practice-generate"><span>Generate practice</span><span aria-hidden="true">→</span></button><p id="practice-status" class="practice-status" role="status"></p></div>';const countSelect=$('#practice-count');countSelect.onchange=()=>{$('#practice-time-preview').innerHTML='<span>◷ <b>'+(Number(countSelect.value))+' minutes</b> estimated</span><span>One minute per question</span><span>Auto-submit and AI grading</span>'};$('#practice-generate').onclick=async()=>{const subject=$('#practice-subject').value,topic=$('#practice-topic').value.trim(),count=Number(countSelect.value)||10;$('#practice-generate').disabled=true;$('#practice-status').textContent='Generating original questions…';try{const r=await api('/practice/generate',{method:'POST',body:JSON.stringify({subject,topic,level:state.user?.class_level||'Not specified',count})});state.quizQuestions=r.questions;state.quizSubject=subject;state.quizIndex=0;state.quizScore=0;state.quizDone=false;state.quizGrading=false;state.quizFeedback='';state.quizAnswers=Array(r.questions.length).fill(null);startQuizTimer();renderQuiz()}catch(e){$('#practice-status').textContent=e.message}finally{if($('#practice-generate'))$('#practice-generate').disabled=false}};return}
 if(state.quizDone){if(state.quizGrading){card.innerHTML='<div class="grading-state"><span class="grading-spinner"></span><div><div class="eyebrow">ANSWERS LOCKED</div><h2>AI is reviewing your work…</h2><p>Your answers are locked. Please wait while GetLearny prepares your feedback.</p></div></div>';return}card.innerHTML='<div class="eyebrow">PRACTICE GRADED</div><h2>'+state.quizScore+' / '+state.quizQuestions.length+'</h2><p>'+Math.round(state.quizScore/state.quizQuestions.length*100)+'% · '+esc(state.quizSubject)+'</p><div class="ai-grade-feedback"><b>Feedback from your review</b><p>'+markdownLite(state.quizFeedback||'Review the explanations and try another set.')+'</p></div><p>Your answers are locked. Review the result in your test history.</p><button class="button button-primary" id="practice-again">Generate another set →</button>';$('#practice-again').onclick=()=>{state.quizQuestions=[];state.quizDone=false;state.quizAnswers=[];state.quizFeedback='';state.quizGrading=false;renderQuiz()};return}
 const q=state.quizQuestions[state.quizIndex],chosen=state.quizAnswers[state.quizIndex];
 card.innerHTML='<div class="timed-exam-header"><div><div class="eyebrow">TIMED AI PRACTICE</div><h2>'+esc(state.quizSubject)+'</h2><p>Question '+(state.quizIndex+1)+' of '+state.quizQuestions.length+'</p></div><div class="countdown-pill"><span>TIME LEFT</span><strong id="quiz-countdown">'+formatQuizTime(state.quizDeadline-Date.now())+'</strong></div></div><div class="progress-line"><span style="width:'+((state.quizIndex+1)/state.quizQuestions.length*100)+'%"></span></div><h3 class="exam-question">'+esc(q.question)+'</h3><div class="exam-options">'+q.options.map((o,i)=>'<button type="button" class="quiz-option '+(Number(chosen)===i?'selected':'')+'" data-choice="'+i+'"><span class="quiz-letter">'+('ABCD'[i])+'</span>'+esc(o)+'</button>').join('')+'</div><div class="exam-footer"><span>'+state.quizAnswers.filter(x=>x!==null&&x!==undefined).length+' / '+state.quizQuestions.length+' answered</span><div class="exam-nav">'+(state.quizIndex>0?'<button class="button button-light" id="quiz-prev" type="button">← Previous</button>':'')+(state.quizIndex<state.quizQuestions.length-1?'<button class="button button-primary" id="quiz-next" type="button">Next question →</button>':'<button class="button button-primary" id="quiz-submit" type="button">Submit & grade →</button>')+'</div></div><p class="form-hint">You can change answers until you submit or time expires.</p>';
 $$('[data-choice]').forEach(b=>b.onclick=()=>{if(Date.now()>=state.quizDeadline){finishTimedQuiz(true);return}state.quizAnswers[state.quizIndex]=Number(b.dataset.choice);renderQuiz()});if($('#quiz-prev'))$('#quiz-prev').onclick=()=>{state.quizIndex--;renderQuiz()};if($('#quiz-next'))$('#quiz-next').onclick=()=>{state.quizIndex++;renderQuiz()};if($('#quiz-submit'))$('#quiz-submit').onclick=()=>finishTimedQuiz(false)
}
function renderRecords(){const journal=$('#journal-list');journal.innerHTML=state.journal.length?state.journal.map(e=>`<article class="record"><div class="record-top"><span>${esc(new Date(e.created_at||e.date||Date.now()).toLocaleDateString())}</span><span>REFLECTION</span></div><b>${esc(e.learned)}</b>${e.difficult?`<p>Challenge: ${esc(e.difficult)}</p>`:''}${e.next_step?`<p>Next step: ${esc(e.next_step)}</p>`:''}</article>`).join(''):'<div class="record"><p>No reflections yet. Your first note can be just one sentence.</p></div>';
$('#test-list').innerHTML=state.tests.length?state.tests.map(t=>`<article class="record"><div class="record-top"><span>${esc(new Date(t.taken_at||t.date||Date.now()).toLocaleDateString())}</span><span>${Number(t.score/t.max_score*100).toFixed(0)}%</span></div><b>${esc(t.title)} · ${esc(t.subject)}</b><p>Score: ${esc(t.score)} / ${esc(t.max_score)}</p></article>`).join(''):'<div class="record"><p>No tests recorded yet. Add your next class test or practice result above.</p></div>'}
function localRead(key){try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return []}}function localWrite(key,v){localStorage.setItem(key,JSON.stringify(v))}
async function loadDashboard(){
  const connection=$('#connection');if(connection)connection.textContent=navigator.onLine?'Connecting to GetLearny…':'Device offline · local mode';
  if(state.token&&state.api){try{const me=await api('/me');state.user=me.user;localStorage.setItem('gl_user',JSON.stringify(state.user))}catch{}}
  renderSubjects();renderSidebarAccount();renderDocumentSubjectOptions();
  state.journal=[];state.tests=[];state.logs=[];
  const localJournal=localRead('gl_journal'),localTests=localRead('gl_tests'),localLogs=localRead('gl_logs');
  try{
    const health=await api('/health');
    const healthy=health.status==='ok'&&health.database?.connected;
    $('#connection').textContent=healthy?(state.token?'Checking sync…':'Online · sign in to sync'):(health.database?.configured?'Database needs attention':'API online · database not configured');
    $('.status-dot').style.background=healthy?'#26ad72':'#f0b84d';
  }catch{
    $('#connection').textContent='Server unreachable';
    $('.status-dot').style.background='#d65c55';
  }
  if(state.token&&state.api){
    try{
      const [d,j,t,l]=await Promise.all([api('/dashboard'),api('/journal'),api('/tests'),api('/learning-logs')]);
      $('#stat-topics').textContent=d.progress?.completedTopics??0;
      $('#stat-time').textContent=`${d.progress?.minutesStudied??0} min`;
      $('#stat-tests').textContent=d.tests?.tests??t.tests.length;
      $('#stat-journal').textContent=d.journal?.journal_entries??j.entries.length;
      state.journal=j.entries;state.tests=t.tests;state.logs=l.logs;
      $('#connection').textContent='Online · progress synced';
      $('.status-dot').style.background='#26ad72';
    }catch(e){
      $('#stat-topics').textContent='—';$('#stat-time').textContent='—';$('#stat-tests').textContent='—';$('#stat-journal').textContent='—';
      $('#connection').textContent=e.message.includes('Session expired')?'Sign in again':'Sync needs attention';
      $('.status-dot').style.background='#f0b84d';
    }
  }else{
    $('#stat-topics').textContent=localLogs.filter(l=>l.status==='completed').length;
    $('#stat-time').textContent=`${localLogs.reduce((a,l)=>a+(l.minutes_spent||0),0)} min`;
    $('#stat-tests').textContent=localTests.length;$('#stat-journal').textContent=localJournal.length;
  }
  renderRecords();
  if(typeof renderRevisionInsights==='function')renderRevisionInsights();
  $('#user-name').textContent=state.user?.name||'Student';
  $('#auth-state').textContent=state.token?'Account connected':'Sign in to sync your progress';
  $('#greeting').textContent=`${state.user?.name?`Welcome back, ${state.user.name.split(' ')[0]}.`:'A little progress adds up.'}`;
}
function fillProfile(){$('#api-url').value=state.api;$('#sign-out').classList.toggle('hidden',!state.token);$('#auth-state').textContent=state.token?'Account connected':'Sign in to sync your progress';const avatar=state.user?.avatar_data;$('#avatar-preview').innerHTML=avatar?'<img src="'+avatar+'" alt="Profile picture">':esc((state.user?.name||'G').slice(0,1).toUpperCase());const settings=$('#profile-settings-form');if(settings){settings.classList.toggle('hidden',!state.token);settings.elements.class_level.value=state.user?.class_level||'';settings.elements.subjects.value=Array.isArray(state.user?.subjects)?state.user.subjects.join(', '):'';}$('#auth-form').classList.toggle('hidden',!!state.token);renderSidebarAccount();renderDocumentSubjectOptions();}
