function renderDocuments(rows){
 const target=$('#document-list');
 if(!rows||!rows.length){target.innerHTML='<article class="record"><p>No files uploaded yet. Add your first PDF or text note above.</p></article>';return;}
 target.innerHTML=rows.map(d=>{
  const status=d.processing_status||'saved';
  const askForm=status==='ready'?'<details class="document-ask"><summary>Ask the AI tutor about this file</summary><form class="document-ask-form" data-document-id="'+esc(d.id)+'"><label>Your question<textarea name="question" required minlength="3" maxlength="1000" placeholder="Explain the main idea in this document…"></textarea></label><button class="button button-primary" type="submit">Ask tutor</button><p class="form-message" aria-live="polite"></p></form></details>':'';
  const ocrAction=(status==='needs_ocr'||status==='ocr_failed')?'<div class="ocr-action"><p class="form-hint">'+(status==='needs_ocr'?'Text extraction is needed before the tutor can read this material.':'Text extraction did not finish. You can retry OCR.')+'</p><button class="button button-light" data-document-ocr="'+esc(d.id)+'" type="button">Run OCR ↻</button><p class="form-message" role="status"></p></div>':'';
  const type=(d.mime_type==='application/pdf'?'PDF':(d.mime_type||'').startsWith('image/')?'IMG':(d.original_name.split('.').pop()||'FILE').toUpperCase());
  return '<article class="record document-record"><span class="soft-pill">'+esc(d.subject_name||'General')+'</span><div class="document-type">'+esc(type)+'</div><div class="document-info"><b>'+esc(d.original_name)+'</b><p>'+(Number(d.size_bytes)/1024).toFixed(0)+' KB · '+esc(new Date(d.created_at).toLocaleDateString())+'</p><span class="document-status status-'+esc(status)+'">'+esc(status.replace(/_/g,' '))+'</span></div><div class="document-actions"><button class="button button-light" data-document-download="'+esc(d.id)+'" type="button">Open / save</button></div>'+ocrAction+askForm+'</article>';
 }).join('');
 target.querySelectorAll('[data-document-ocr]').forEach(b=>b.onclick=async()=>{const card=b.closest('.document-record'),msg=card?.querySelector('.ocr-action .form-message');b.disabled=true;b.textContent='Reading file…';if(msg)msg.textContent='Retrieving your file and extracting text. Large PDFs can take a little longer.';try{const r=await api('/documents/'+encodeURIComponent(b.dataset.documentOcr)+'/ocr',{method:'POST',timeoutMs:90000,body:JSON.stringify({})});toast(r.message||'Text extraction complete.');await loadDocuments()}catch(e){if(msg)msg.textContent=e.message;b.disabled=false;b.textContent='Retry OCR ↻'}});
 target.querySelectorAll('[data-document-download]').forEach(b=>b.onclick=async()=>{try{const r=await fetch(state.api.replace(/\/$/,'')+'/documents/'+encodeURIComponent(b.dataset.documentDownload),{headers:state.token?{Authorization:'Bearer '+state.token}:{}});if(!r.ok){let details='';try{details=(await r.json()).error||''}catch{}throw new Error(details||'Could not retrieve this file. Try again shortly.')}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='study-material';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}});
 target.querySelectorAll('.document-ask-form').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type="submit"]'),message=form.querySelector('.form-message'),question=new FormData(form).get('question');button.disabled=true;message.textContent='The tutor is reading your file…';try{const r=await api('/documents/'+encodeURIComponent(form.dataset.documentId)+'/ask',{method:'POST',body:JSON.stringify({question})});message.innerHTML='<strong>GetLearny tutor</strong><div class="ai-answer">'+esc(r.answer).split(String.fromCharCode(10)).join('<br>')+'</div>';}catch(err){message.textContent=err.message;}finally{button.disabled=false;}}));
}
async function uploadStudyMaterialToCloudinary(file,subjectName,materialTitle,onStatus){
 if(file.size>100*1024*1024)throw new Error('Choose a file smaller than 100 MB.');
 onStatus?.('Preparing secure Cloudinary upload…');
 const signed=await api('/documents/upload-signature',{method:'POST',body:JSON.stringify({})});
 const body=new FormData();body.append('file',file);body.append('api_key',signed.api_key);body.append('timestamp',String(signed.timestamp));body.append('folder',signed.folder);body.append('public_id',signed.public_id);body.append('signature',signed.signature);
 onStatus?.('Uploading directly to Cloudinary…');
 const response=await fetch('https://api.cloudinary.com/v1_1/'+encodeURIComponent(signed.cloud_name)+'/auto/upload',{method:'POST',body});
 const asset=await response.json().catch(()=>({}));if(!response.ok)throw new Error(asset.error?.message||'Cloudinary could not upload this file. Check the Cloudinary account limits and configuration.');
 onStatus?.('Saving material details…');
 return api('/documents/register-cloudinary',{method:'POST',body:JSON.stringify({secure_url:asset.secure_url,public_id:asset.public_id,original_name:file.name,mime_type:file.type||asset.resource_type||'application/octet-stream',size_bytes:file.size,subject_name:subjectName||'General',material_title:materialTitle||file.name})});
}
