async function loadSubjectMaterials(subjectName){const target=$('#subject-material-list');if(!target)return;target.innerHTML='<div class="record"><p>Loading subject materials…</p></div>';try{const r=await api('/documents');const docs=(r.documents||[]).filter(d=>String(d.subject_name||'General').toLowerCase()===subjectName.toLowerCase());if(!docs.length){target.innerHTML='<div class="material-empty"><b>No materials yet</b><p>Upload your first notes for '+esc(subjectName)+'.</p></div>';return}target.innerHTML=docs.map(d=>'<article class="record document-record"><span class="soft-pill">'+esc(d.processing_status||'saved')+'</span><div class="document-type">'+esc((d.original_name.split('.').pop()||'FILE').toUpperCase())+'</div><div class="document-info"><b>'+esc(d.original_name)+'</b><p>'+(Number(d.size_bytes)/1024).toFixed(0)+' KB · '+esc(new Date(d.created_at).toLocaleDateString())+'</p></div><button type="button" class="button button-light" data-material-open="'+esc(d.id)+'">Open / save</button>'+(d.processing_status==='ready'?'<details class="document-ask"><summary>Ask AI about these notes</summary><form class="document-ask-form" data-document-id="'+esc(d.id)+'"><label>Your question<textarea name="question" required minlength="3" maxlength="1000" placeholder="Explain this topic simply…"></textarea></label><button class="button button-primary" type="submit">Ask tutor →</button><p class="form-message" role="status"></p></form></details>':'<div class="ocr-action"><p class="form-hint">'+(d.processing_status==='needs_ocr'?'Text extraction is needed before the tutor can read this material.':d.processing_status==='ocr_failed'?'OCR could not read this material yet.':'Text extraction status: '+esc(d.processing_status||'saved'))+'</p>'+(d.processing_status==='needs_ocr'||d.processing_status==='ocr_failed'?'<button type="button" class="button button-light" data-material-ocr="'+esc(d.id)+'">Run OCR ↻</button>':'')+'</div>')+'</article>').join('');target.querySelectorAll('[data-material-ocr]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;btn.textContent='Running OCR…';try{const r=await api('/documents/'+encodeURIComponent(btn.dataset.materialOcr)+'/ocr',{method:'POST',timeoutMs:90000,body:JSON.stringify({})});toast(r.message||'OCR complete.');await loadSubjectMaterials(subjectName)}catch(err){toast(err.message);btn.disabled=false;btn.textContent='Retry OCR ↻'}});target.querySelectorAll('[data-material-open]').forEach(btn=>btn.onclick=async()=>{try{const response=await fetch(state.api.replace(/\/$/,'')+'/documents/'+encodeURIComponent(btn.dataset.materialOpen),{headers:{Authorization:'Bearer '+state.token}});if(!response.ok)throw new Error('Could not retrieve this file');const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='study-material';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(err){toast(err.message)}});target.querySelectorAll('.document-ask-form').forEach(form=>form.onsubmit=async ev=>{ev.preventDefault();const msg=form.querySelector('.form-message'),btn=form.querySelector('button');btn.disabled=true;msg.textContent='AI is reading your notes…';try{const answer=await api('/documents/'+encodeURIComponent(form.dataset.documentId)+'/ask',{method:'POST',body:JSON.stringify({question:new FormData(form).get('question')})});msg.textContent=answer.answer||'No answer returned.'}catch(err){msg.textContent=err.message}finally{btn.disabled=false}})}catch(err){target.innerHTML='<div class="record"><p>'+esc(err.message)+'</p></div>'}}


// AI tutor: live, account-scoped context from progress, tests, reflections and readable study files.
const tutorState={messages:[],busy:false,context:null,initialized:false};
function tutorSubjects(){const select=$('#tutor-subject');if(!select)return;const current=select.value;select.innerHTML='<option value="">All my subjects</option>'+getLearnerSubjects().map(s=>'<option value="'+esc(s)+'">'+esc(s)+'</option>').join('');if(getLearnerSubjects().includes(current))select.value=current;}
async function loadTutorContext(){const target=$('#tutor-context-list');if(!target)return;if(!state.token){target.innerHTML='<div class="tutor-context-empty">Sign in to connect your personal learning history and files.</div>';return;}target.innerHTML='<div class="tutor-context-empty">Refreshing your study context…</div>';try{const [docs,logs,tests,journal,dashboard]=await Promise.all([api('/documents'),api('/learning-logs'),api('/tests'),api('/journal'),api('/dashboard')]);const ready=(docs.documents||[]).filter(d=>d.processing_status==='ready');const data={documents:docs.documents||[],logs:logs.logs||[],tests:tests.tests||[],journal:journal.entries||[],dashboard:dashboard||{}};tutorState.context=data;target.innerHTML='<div><span>▤</span><span><b>Study files</b><small>'+ready.length+' readable · '+((docs.documents||[]).length-ready.length)+' need processing</small></span></div><div><span>◷</span><span><b>Progress & tests</b><small>'+(data.logs.length)+' learning logs · '+data.tests.length+' test results</small></span></div><div><span>▧</span><span><b>Learning journal</b><small>'+data.journal.length+' saved reflections</small></span></div><div><span>◎</span><span><b>Learning profile</b><small>'+esc(state.user?.class_level||'Class not set')+' · '+getLearnerSubjects().length+' subjects</small></span></div>';return data;}catch(err){target.innerHTML='<div class="tutor-context-empty">Could not refresh context: '+esc(err.message)+'</div>';throw err;}}
function initTutor(){tutorSubjects();if(!tutorState.initialized){tutorState.initialized=true;$('#tutor-chat-form')?.addEventListener('submit',sendTutorMessage);$('#tutor-question')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#tutor-chat-form').requestSubmit();}});$('#tutor-clear-chat')?.addEventListener('click',()=>{tutorState.messages=[];renderTutorMessages();$('#tutor-chat-status').textContent='New conversation started. Your saved learning data is unchanged.';});$('#tutor-refresh-context')?.addEventListener('click',()=>loadTutorContext().then(()=>toast('Learning context refreshed.')).catch(()=>{}));$('#view-tutor')?.querySelectorAll('[data-tutor-prompt]').forEach(b=>b.addEventListener('click',()=>{const q=$('#tutor-question');q.value=b.dataset.tutorPrompt;q.focus();q.style.height='auto';q.style.height=Math.min(q.scrollHeight,160)+'px';}));$('#view-tutor')?.querySelectorAll('[data-tutor-go]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.tutorGo)));}if(!state.token){$('#tutor-chat-status').textContent='Sign in to chat with your tutor and connect your private learning records.';loadTutorContext().catch(()=>{});return;}$('#tutor-chat-status').textContent='Your tutor uses your account data only when you send a message.';loadTutorContext().catch(()=>{});}
function renderTutorMessages(){const target=$('#tutor-messages');if(!target)return;if(!tutorState.messages.length){target.innerHTML='<div class="tutor-welcome"><div class="welcome-mark">✦</div><span class="eyebrow">LET’S MAKE IT CLICK</span><h2>What are we working on today?</h2><p>Ask a question, request a simpler explanation, or let me help you revise a topic you’ve struggled with.</p><div class="tutor-prompt-grid"><button type="button" data-tutor-prompt="Teach me a difficult topic step by step, with a worked example and a quick check.">Teach me a topic <span>→</span></button><button type="button" data-tutor-prompt="Look at my recent learning and test results and recommend what I should revise next.">What should I revise? <span>→</span></button><button type="button" data-tutor-prompt="Help me understand my study notes, explain the key ideas simply, and point out what I should remember for WASSCE.">Explain my notes <span>→</span></button><button type="button" data-tutor-prompt="Give me a short WASSCE-style revision plan for the topic I am studying, with a few questions to check my understanding.">Prepare for WASSCE <span>→</span></button></div></div>';target.querySelectorAll('[data-tutor-prompt]').forEach(b=>b.onclick=()=>{$('#tutor-question').value=b.dataset.tutorPrompt;$('#tutor-question').focus()});return;}target.innerHTML=tutorState.messages.map(m=>'<article class="tutor-message '+(m.role==='user'?'from-user':'from-ai')+'"><div class="message-avatar">'+(m.role==='user'?esc((state.user?.name||'You').slice(0,1).toUpperCase()):'✦')+'</div><div class="message-body"><div class="message-meta">'+(m.role==='user'?'You':'GetLearny Tutor')+'</div><div class="message-content">'+(m.pending?'<span class="tutor-thinking"><i></i><i></i><i></i> Connecting the dots…</span>':markdownLite(m.content))+'</div>'+(m.sources?.length?'<div class="tutor-source-row">Context used: '+m.sources.map(esc).join(' · ')+'</div>':'')+'</div></article>').join('');target.scrollTop=target.scrollHeight;}
async function sendTutorMessage(e){e?.preventDefault();const input=$('#tutor-question'),question=input.value.trim();if(!question||tutorState.busy)return;if(!state.token){$('#tutor-chat-status').textContent='Sign in to use the AI tutor with your personal study context.';showView('profile');return;}tutorState.messages.push({role:'user',content:question});input.value='';input.style.height='auto';tutorState.messages.push({role:'assistant',content:'',pending:true});tutorState.busy=true;$('#tutor-send').disabled=true;$('#tutor-chat-status').textContent='Checking your study context and preparing an answer…';renderTutorMessages();try{const recent=tutorState.messages.filter(m=>!m.pending).slice(-12).map(m=>({role:m.role,content:m.content}));const r=await api('/tutor/chat',{method:'POST',timeoutMs:60000,body:JSON.stringify({question,subject:$('#tutor-subject').value||'',use_materials:$('#tutor-use-materials').checked,history:recent})});tutorState.messages[tutorState.messages.length-1]={role:'assistant',content:r.answer||'The tutor returned an empty answer. Please try again.',sources:r.context_sources||[]};$('#tutor-chat-status').textContent=(r.generatedBy||'AI tutor')+' · '+(r.context_summary||'Answer ready');}catch(err){tutorState.messages.pop();tutorState.messages.push({role:'assistant',content:'I couldn’t answer that just now. '+err.message+' Your saved progress and notes have not been changed.'});$('#tutor-chat-status').textContent=/timed out|timeout/i.test(err.message)?'Gemini timed out after trying the available models. The timeout is shown in the chat above; please retry shortly.':err.message;}finally{tutorState.busy=false;$('#tutor-send').disabled=false;renderTutorMessages();}}

function renderDocumentSubjectOptions(){const select=$('#document-subject');if(!select)return;const chosen=select.value;const subjects=getLearnerSubjects();select.innerHTML='<option value="General">General / unassigned</option>'+subjects.map(s=>'<option value="'+esc(s)+'">'+esc(s)+'</option>').join('');if(subjects.includes(chosen))select.value=chosen;}
function renderSidebarAccount(){const name=state.user?.name||'Student';const image=state.user?.avatar_data;const nameNode=$('#user-name');if(nameNode)nameNode.textContent=name;const avatarNode=$('#profile-open .avatar');if(avatarNode)avatarNode.innerHTML=image?'<img src="'+image+'" alt="" referrerpolicy="no-referrer">':esc(name.slice(0,1).toUpperCase());const logout=$('#sidebar-sign-out');if(logout){logout.classList.toggle('hidden',!state.token);logout.setAttribute('aria-label','Sign out');logout.title='Sign out';}}

const savedTheme=localStorage.getItem('gl_theme')||'light';setTheme(savedTheme);
let notificationWorker=null,reminderTimer=null;
async function setupNotifications(){if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('/sw.js');notificationWorker=await navigator.serviceWorker.ready;}catch(e){console.warn('Service worker unavailable',e)}}loadNotificationSettings();if(localStorage.getItem('gl_reminder_enabled')==='true')startReminderLoop();}
function notificationState(){if(!('Notification'in window))return 'This browser does not support device notifications.';if(Notification.permission==='granted')return 'Notifications are enabled for this browser on this device.';if(Notification.permission==='denied')return 'Notifications are blocked in browser settings. Allow them there to continue.';return 'Notifications are off. Enable them to allow device alerts.';}
function loadNotificationSettings(){const status=$('#notification-status');if(status){status.textContent=notificationState();if(state.token&&'serviceWorker'in navigator)api('/notifications/public-key').then(c=>{status.textContent+=' '+(c.configured?'Background push is configured for this account.':'Background push while the site is closed still needs VAPID keys configured by the project owner.');}).catch(()=>{});}const t=$('#reminder-time');if(t)t.value=localStorage.getItem('gl_reminder_time')||'19:00';const c=$('#reminder-enabled');if(c)c.checked=localStorage.getItem('gl_reminder_enabled')==='true';const e=$('#enable-notifications');if(e)e.textContent=('Notification'in window&&Notification.permission==='granted')?'Notifications enabled':'Enable notifications';}
function vapidBytes(value){const padded=value+'='.repeat((4-value.length%4)%4);const raw=atob(padded.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0));}
async function subscribePush(){if(!state.token){toast('Sign in to connect background notifications to your account.');return false;}const config=await api('/notifications/public-key');if(!config.configured||!config.publicKey){toast('Device alerts work now. Background web push still needs VAPID keys configured by the project owner.');return false;}const reg=await navigator.serviceWorker.ready;let subscription=await reg.pushManager.getSubscription();if(!subscription)subscription=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:vapidBytes(config.publicKey)});await api('/notifications/subscriptions',{method:'POST',body:JSON.stringify({subscription:subscription.toJSON(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Africa/Accra',reminderTime:localStorage.getItem('gl_reminder_time')||'19:00',dailyReminder:localStorage.getItem('gl_reminder_enabled')==='true'})});return true;}
async function requestNotifications(){if(!('Notification'in window)){toast('This browser does not support device notifications.');return false;}try{const permission=await Notification.requestPermission();loadNotificationSettings();if(permission!=='granted'){toast('Allow notifications in browser settings to receive device alerts.');return false;}if(notificationWorker?.active)notificationWorker.active.postMessage({type:'SHOW_NOTIFICATION',payload:{title:'GetLearny is ready',body:'Device notifications are enabled. Keep making progress.',tag:'getlearny-enabled'}});else new Notification('GetLearny is ready',{body:'Device notifications are enabled.'});if(state.token)try{await subscribePush()}catch(e){console.warn('Push subscription not saved',e)}toast('Device notifications enabled.');return true;}catch(e){toast('Could not enable notifications on this device.');return false;}}
async function sendDeviceNotification(title,body,tag='getlearny-test'){if(!('Notification'in window)||Notification.permission!=='granted'){toast('Enable device notifications first.');return;}if(state.token&&tag==='getlearny-test'){try{await api('/notifications/test',{method:'POST',body:JSON.stringify({})});}catch(e){console.info('Background push unavailable; using this device notification instead',e.message)}}try{if('serviceWorker'in navigator){const reg=notificationWorker||await navigator.serviceWorker.ready;if(reg?.active){reg.active.postMessage({type:'SHOW_NOTIFICATION',payload:{title,body,tag,url:'/'}});toast('Test notification requested. Check your device notification shade.');return;}}}catch(e){console.info('Service-worker notification unavailable',e.message)}try{new Notification(title,{body,tag});toast('Test notification shown.');}catch(e){toast('Browser blocked the notification. Check site notification permissions.');}}
function startReminderLoop(){if(reminderTimer)clearInterval(reminderTimer);reminderTimer=setInterval(()=>{if(localStorage.getItem('gl_reminder_enabled')!=='true'||!('Notification'in window)||Notification.permission!=='granted')return;const now=new Date(),time=localStorage.getItem('gl_reminder_time')||'19:00',key='gl_last_reminder_date';if(now.toTimeString().slice(0,5)===time&&localStorage.getItem(key)!==now.toDateString()){localStorage.setItem(key,now.toDateString());sendDeviceNotification('Time for a GetLearny study session','Take one small step toward your WASSCE goals.','getlearny-daily-reminder');}},30000);}
$('#notification-open').addEventListener('click',()=>showView('notifications'));
$('#enable-notifications').addEventListener('click',requestNotifications);
$('#test-notification').addEventListener('click',()=>sendDeviceNotification('GetLearny test notification','Your device notifications are working.','getlearny-test'));
$('#reminder-form').addEventListener('submit',e=>{e.preventDefault();const enabled=$('#reminder-enabled').checked;localStorage.setItem('gl_reminder_time',$('#reminder-time').value);localStorage.setItem('gl_reminder_enabled',String(enabled));if(enabled&&(!('Notification'in window)||Notification.permission!=='granted')){localStorage.setItem('gl_reminder_enabled','false');$('#reminder-message').textContent='Enable device notifications first, then save the reminder.';loadNotificationSettings();return;}if(enabled)startReminderLoop();else if(reminderTimer){clearInterval(reminderTimer);reminderTimer=null;}if(state.token&&'serviceWorker'in navigator)subscribePush().catch(e=>console.info('Background push setup is not available yet',e.message));$('#reminder-message').textContent=enabled?'Daily reminder saved. This browser reminder runs while the site is open; push delivery while closed needs VAPID setup.':'Daily reminder turned off.';toast('Reminder settings saved.');});
window.addEventListener('error',event=>{console.error('GetLearny application error:',event.error||event.message);const label=$('#connection');if(label)label.textContent='App error · refresh the page';const dot=$('.status-dot');if(dot)dot.style.background='#d65c55';});
window.addEventListener('unhandledrejection',event=>{console.error('GetLearny async error:',event.reason);});
window.addEventListener('offline',()=>{$('#connection').textContent='Device offline · local mode';$('.status-dot').style.background='#d65c55';});
window.addEventListener('online',()=>{$('#connection').textContent='Reconnecting…';$('.status-dot').style.background='#f0b84d';loadDashboard();});
setupNotifications();const now=new Date();$('#today').textContent=now.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();if(state.api)$('#api-url').value=state.api;loadDashboard();
